import{_ as l,l as n,o as e,c as r,v as t,p as E,x as o,d as s,i as p,S as B}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"产品差异与霍特林","description":"","frontmatter":{"title":"产品差异与霍特林","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hotelling.md","filePath":"econ/hotelling.md","lastUpdated":1789023840000}'),d={name:"econ/hotelling.md"};function c(h,a,A,_,m,u){const i=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="产品差异与霍特林" tabindex="-1">产品差异与霍特林 <a class="header-anchor" href="#产品差异与霍特林" aria-label="Permalink to &quot;产品差异与霍特林&quot;">​</a></h1><div class="epigraph"><p>买者沿一条线分布，卖者选址再定价；运费把本来同质的产品拆开，价格不再一刀切到边际成本。</p><footer>—— 据 Hotelling, Stability in Competition, The Economic Journal, 1929 整理</footer></div><p><a href="/econ/predatory-pricing">上一课</a>（掠夺性定价）。仍在同质产品上比较先动与同时。本课不重讲反应曲线的切点。缺口是：<a href="/econ/bertrand-capacity">伯川德</a>的赢者通吃来自完全替代。只要产品在空间或特征上略有不同，低价不能抢走全部需求，加价可以在价格竞争里存活。市场结构课序的主干在此收束：差异本身是策略，然后把局部市场交给一般均衡课的盒子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单位区间 \\([0,1]\\) 上消费者均匀分布，到商店的线性运费为 \\(t\\)。两家先选位置 \\(x_1,x_2\\)，再选价格。无差异消费者把市场切开，剩余需求有斜率，伯川德悖论消失。缺口不是再写一次勒纳公式，而是：<strong>位置如何改变价格阶段的弹性，以及均衡位置会不会挤在一起。</strong></p><p>价格阶段：给定位置，距离越近，交叉弹性越高，均衡加价越低。位置阶段：靠近对手能抢份额，但会加剧随后的价格战。Hotelling 原文在线性运费下得到最小差异——两家挤向中点。运费改成二次后，d&#39;Aspremont、Gabszewicz 与 Thisse 证明价格均衡存在，且均衡是最大差异：两家走到端点。本课把「差异是缓和价格竞争的工具」钉死，不把 1929 的中点当成一般定理。</p><h3 id="差异不是垄断-也不是另一条需求曲线外生给定" tabindex="-1">差异不是垄断，也不是另一条需求曲线外生给定 <a class="header-anchor" href="#差异不是垄断-也不是另一条需求曲线外生给定" aria-label="Permalink to &quot;差异不是垄断，也不是另一条需求曲线外生给定&quot;">​</a></h3><p>每家仍面对向下的剩余需求，勒纳仍可读，但弹性由 \\(t\\) 与距离内生。把差异写成「每家都是小垄断者」而不写位置博弈，会漏掉靠近与远离的权衡。也不要把 \\(t\\) 写成偏好课的 \\(u\\)：运费是购物的物质成本，不是伯努利函数。</p><p><span class="marginnote">线性运费下，位置太近时价格均衡可以不存在（底切循环）。二次运费修补存在性。引用霍特林时要声明运费形式，否则「最小差异」与「最大差异」会对着打。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段、逆向归纳：先解给定 \\((x_1,x_2)\\) 的价格均衡，把利润写成位置的函数，再选址。对称均衡便于算。\\(t\\) 上升：价格阶段加价上升，位置阶段更敢靠近——运费像天然的产能约束，挡住赢者通吃。\\(t\\to 0\\) 回到伯川德。圆上、多维特征、多家厂商，几何更烦，机制不变：横差异缓和价格。</p><p>本课不引入广告、质量（纵差异）的同时选择。质量改变需求截距，位置改变替代程度；后者才是对伯川德刀刃的直接补丁。先动选址可以叠斯塔克尔伯格，但教具上两家同时选址已够把课序收住。</p>',12)),(e(),E(B,null,{default:o(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOM%5B%22%E5%90%8C%E8%B4%A8%EF%BC%9A%E4%BC%AF%E5%B7%9D%E5%BE%B7%E6%88%96%E5%8F%A4%E8%AF%BA%22%5D%20--%3E%20LOC%5B%22%E7%BA%BF%E6%80%A7%E5%9F%8E%E5%B8%82%EF%BC%9A%E4%BD%8D%E7%BD%AE%20%2B%20%E8%BF%90%E8%B4%B9%20t%22%5D%0A%20%20LOC%20--%3E%20P%5B%22%E4%BB%B7%E6%A0%BC%E9%98%B6%E6%AE%B5%EF%BC%9A%E5%8A%A0%E4%BB%B7%E9%9A%8F%E8%B7%9D%E7%A6%BB%E5%8D%87%22%5D%0A%20%20P%20--%3E%20X%5B%22%E9%80%89%E5%9D%80%EF%BC%9A%E4%BB%BD%E9%A2%9D%20vs%20%E4%BB%B7%E6%A0%BC%E6%88%98%22%5D%0A%20%20X%20--%3E%20DIFF%5B%22%E5%B7%AE%E5%BC%82%E5%86%85%E7%94%9F%EF%BC%8C%E6%82%96%E8%AE%BA%E6%B6%88%E5%A4%B1%22%5D%0A%20%20DIFF%20--%3E%20LATER%5B%22%E4%B8%8B%E8%AF%BE%E7%A8%8B%EF%BC%9A%E4%BB%8E%E5%B1%80%E9%83%A8%E8%A1%97%E9%81%93%E5%88%B0%E5%9F%83%E5%A5%87%E6%B2%83%E6%80%9D%E7%9B%92%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>线性城市也可以读成偏好谱：甜度、政治光谱、颜色。运输是「不合心意」的效用损失，不一定是公里数。\\(t\\to 0\\) 或两店重合，交叉弹性无穷，回到同质伯川德。本课横向两店已够收束市场结构课序。</p><p>街道是局部市场。两种商品、两个人的总量配置，下一课程用埃奇沃思盒来画；不要把 \\([0,1]\\) 上的份额写成一般均衡的可行配置。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>切开市场的机制是运费：离商店更近的人，对对方提价不那么敏感，剩余需求倾斜。选址向中靠的机制是「偷份额」；向外走的机制是「软化随后的 \\(p\\)」。哪一边赢，取决于运费曲率与价格均衡是否存在。无论端点还是中点，只要 \\(t\\gt 0\\)，价格就不会落到共同的 MC——这才是对上一课悖论的回答。</p><p>与数量领导的关系：位置是另一种承诺，改变的是需求形状而不是产能。沉没的店址一旦落下，价格阶段在既定差异上打，类似产能先沉没。市场结构课序从接受价格、到垄断、到同时量、到同时价、到先动、到选址，全部是在改「谁把什么钉死」。</p><p>\\([0,1]\\) 只是特征的教具。颜色、接口、交货时点都可以当位置读；运费 \\(t\\) 则读成「换一家的不适」。机制不依赖真的有一条街。</p><p><span class="marginnote">Hotelling 1929 与 Hotelling 1932 的供给引理不是同一篇。线性城市用 1929；利润函数用 1932。后课一般均衡从街道收回到总量盒子，不再加一家商店。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>搜寻、转换成本、网络效应也能制造有效差异，不必真的有一条街。纵向差异（质量）与本课的横向差异不要混成一个 \\(t\\)。规制最低差异、分区，会把选址约束写进规划，本课不写。</p><p>产品市场到此结束。下一课换坐标系：不再是厂商对消费者的局部定价，而是两人两种商品的可行配置与帕累托集。街道上的「位置」不是埃奇沃思盒里的禀赋点——前者是特征空间，后者是商品总量守恒。限价簿仍不在本栏出现。</p><p>后课默认：横差异用位置与运费进入剩余需求；伯川德悖论在 \\(t\\gt 0\\) 时解除。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>运费把同质产品拆开，价格竞争可以留下加价。</li><li>选址权衡份额与随后的价格战；最小差异不是一般结论。</li><li>市场结构主干止于局部街道；下一课进入交换的盒子。</li><li>不要把霍特林价格写成限价簿价差。</li><li>出处：Hotelling, <em>Economic Journal</em>, 1929；d&#39;Aspremont, Gabszewicz and Thisse, <em>JET</em>, 1979；Mas-Colell, Whinston and Green 第 12 章。</li></ul>',13))])}const D=l(d,[["render",c]]);export{f as __pageData,D as default};
